function maxGames($n) {
    if ($n == 1) return 0;
    if ($n == 2) return 1;
    if ($n == 3) return 2;
    $k = 0;
    while ((1 << ($k + 2)) <= $n) {
        $k++;
    }
    $fib_k_plus_2 = (1 << ($k + 2));
    $fib_k_plus_1 = (1 << ($k + 1));
    $remaining = $n - $fib_k_plus_2;
    if ($remaining == 0) {
        return $k + 1;
    }
    return $k + 1 + maxGames($remaining);
}
