<?php
function maxGames($n) {
    if ($n == 1) return 0;
    if ($n == 2) return 1;
    $a = 1;
    $b = 2;
    while ($b < $n) {
        $next = $a + $b;
        $a = $b;
        $b = $next;
    }
    if ($b == $n) {
        return fibIndex($b);
    } else {
        return fibIndex($a) + maxGames($n - $a);
    }
}

function fibIndex($x) {
    if ($x == 1) return 1;
    $a = 1;
    $b = 2;
    $index = 2;
    while ($b < $x) {
        $next = $a + $b;
        $a = $b;
        $b = $next;
        $index++;
    }
    return $index;
}

